def _sock_out(node, key):
    if node.name == "Group Output" or node.name.startswith("Group Input"):
        for s in node.outputs:
            if s.name == key:
                return s
    for s in node.outputs:
        if s.identifier == key:
            return s
    return None


def _sock_in(node, key):
    if node.name == "Group Output" or node.name.startswith("Group Input"):
        for s in node.inputs:
            if s.name == key:
                return s
    for s in node.inputs:
        if s.identifier == key:
            return s
    return None


def build_tree():
    tree = bpy.data.node_groups.new(TREE_NAME, 'GeometryNodeTree')
    tree.interface.new_socket(name="Geometry", in_out='OUTPUT', socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name="Geometry", in_out='INPUT', socket_type='NodeSocketGeometry')
    s_rad = tree.interface.new_socket(name="radius", in_out='INPUT', socket_type='NodeSocketFloat')
    s_rad.default_value = 0.0
    s_rang = tree.interface.new_socket(name="rang", in_out='INPUT', socket_type='NodeSocketFloat')
    s_rang.default_value = 0.44
    tree.interface.new_socket(name="Object", in_out='INPUT', socket_type='NodeSocketObject')

    N = {}
    for name, blid, loc in NODES:
        n = tree.nodes.new(blid)
        n.name = name
        n.location = loc
        N[name] = n

    for nm, op in VECTOR_OPS.items():
        N[nm].operation = op
    for nm, op in MATH_OPS.items():
        N[nm].operation = op

    N["Mix"].data_type = 'VECTOR'
    try:
        N["Viewer"].data_type = 'FLOAT_VECTOR'
    except Exception:
        pass
    try:
        N["Sample Curve"].mode = 'FACTOR'
    except Exception:
        pass

    for (nm, sid), val in INPUT_VALUES.items():
        sock = _sock_in(N[nm], sid)
        if sock is not None:
            try:
                sock.default_value = val
            except Exception:
                pass

    for fn, fs, tn, ts in LINKS:
        a = _sock_out(N[fn], fs)
        b = _sock_in(N[tn], ts)
        if a is not None and b is not None:
            tree.links.new(a, b)

    tree["cb_exact"] = True
    return tree


def _load_tree():
    raw = base64.b64decode(_BLOB) if _BLOB else None
    tmp = os.path.join(tempfile.gettempdir(), 'cb_embed_gn.blend')
    with open(tmp, 'wb') as f:
        f.write(raw)
    before = set(bpy.data.node_groups.keys())
    with bpy.data.libraries.load(tmp, link=False) as (src, dst):
        dst.node_groups = [n for n in src.node_groups if n == TREE_NAME]
    try:
        os.remove(tmp)
    except OSError:
        pass
    for t in bpy.data.node_groups:
        if t.name not in before and t.type == 'GEOMETRY':
            t["cb_exact"] = True
            t.use_fake_user = True
            return t
    return None


def ensure_tree():
    for t in bpy.data.node_groups:
        if t.type == 'GEOMETRY' and t.get("cb_exact"):
            return t
    return _load_tree()


def create_curve(context):
    cdata = bpy.data.curves.new("BendPath", 'CURVE')
    cdata.dimensions = '3D'
    cdata.fill_mode = 'FULL'
    cdata.resolution_u = 12
    sp = cdata.splines.new('NURBS')
    sp.points.add(4)
    for i, p in enumerate(sp.points):
        p.co = (-2.0 + i, 0.0, 0.0, 1.0)
    sp.order_u = 5
    sp.use_endpoint_u = True
    ob = bpy.data.objects.new("BendPath", cdata)
    context.collection.objects.link(ob)
    return ob


def _poll_curve(self, ob):
    return ob.type == 'CURVE'


class OBJECT_OT_exact_bend_add(bpy.types.Operator):
    bl_idname = "object.exact_bend_add"
    bl_label = "Add Exact Bend"
    bl_description = "Add the exact 'tut bend' Geometry Nodes setup to the active mesh"
    bl_options = {'REGISTER', 'UNDO'}

    radius: bpy.props.FloatProperty(name="radius", default=0.15, min=0.001, soft_max=10.0)
    rang: bpy.props.FloatProperty(name="rang", default=0.255, soft_min=-1.0, soft_max=1.0)
    curve_name: bpy.props.StringProperty(name="Curve", description="Name of an existing curve object; leave empty to auto-create")

    @classmethod
    def poll(cls, context):
        ob = context.active_object
        return ob is not None and ob.type == 'MESH'

    def execute(self, context):
        ob = context.active_object
        tree = ensure_tree()
        curve = bpy.data.objects.get(self.curve_name) if self.curve_name else None
        if curve is not None and curve.type != 'CURVE':
            curve = None
        if curve is None:
            curve = create_curve(context)

        mod = None
        for m in ob.modifiers:
            if m.type == 'NODES' and m.node_group and m.node_group.get("cb_exact"):
                mod = m
                break
        if mod is None:
            mod = ob.modifiers.new(MOD_NAME, 'NODES')
        mod.node_group = tree

        ids = {}
        for item in tree.interface.items_tree:
            if item.item_type == 'SOCKET' and item.in_out == 'INPUT':
                ids[item.name] = item.identifier

        mod[ids["radius"]] = float(self.radius)
        mod[ids["rang"]] = float(self.rang)
        mod[ids["Object"]] = curve
        mod["xb_radius_socket"] = ids["radius"]
        mod["xb_rang_socket"] = ids["rang"]

        self.report({'INFO'}, "Exact bend added: " + ob.name)
        return {'FINISHED'}


class VIEW3D_PT_exact_bend(bpy.types.Panel):
    bl_label = "Bend Exact"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "Bend"

    def draw(self, context):
        lay = self.layout
        col = lay.column(align=True)
        col.operator("object.exact_bend_add", icon='MOD_SIMPLEDEFORM')
        ob = context.active_object
        if ob and ob.type == 'MESH':
            mod = ob.modifiers.get(MOD_NAME)
            if mod:
                rid = mod.get("xb_radius_socket")
                gid = mod.get("xb_rang_socket")
                if rid:
                    box = lay.box()
                    box.prop(mod, '["' + rid + '"]', text="radius", slider=True)
                if gid:
                    box = lay.box()
                    box.prop(mod, '["' + gid + '"]', text="rang", slider=True)


classes = (
    OBJECT_OT_exact_bend_add,
    VIEW3D_PT_exact_bend,
)


def register():
    for c in classes:
        bpy.utils.register_class(c)


def unregister():
    for c in reversed(classes):
        bpy.utils.unregister_class(c)


if __name__ == "__main__":
    register()
